{"output":"#!/usr/bin/env python3
"""
Utilities to automate semantic versioning and VERSION.md generation
for feature, test, and main branches.
"""

from __future__ import annotations

import argparse
import re
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Tuple


SEMVER_RE = re.compile(r"^v?(\d+)\.(\d+)\.(\d+)$")


def run_git(args: Iterable[str]) -> str:
    """Run a git command and return stdout, stripped."""
    result = subprocess.run(
        ["git", *args],
        check=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    if result.returncode != 0:
        raise RuntimeError(f"git {' '.join(args)} failed: {result.stderr.strip()}")
    return result.stdout.strip()


def branch_slug(branch: str) -> str:
    """Return a tag-friendly slug for a branch."""
    return branch.replace("/", "-")


def parse_semver(version: str) -> Tuple[int, int, int]:
    """Parse a semantic version (with optional leading v)."""
    match = SEMVER_RE.match(version)
    if not match:
        raise ValueError(f"Invalid SemVer: {version}")
    return tuple(int(group) for group in match.groups())


def format_semver(parts: Tuple[int, int, int]) -> str:
    """Format a numeric semver tuple back to a string with leading v."""
    return f"v{parts[0]}.{parts[1]}.{parts[2]}"


def bump_semver(prev_version: Optional[str], level: str) -> str:
    """
    Calculate next semantic version.

    If prev_version is None, default versions:
    - major -> v1.0.0
    - minor -> v0.1.0
    - patch -> v0.1.0
    """
    level = level.lower()
    if prev_version:
        major, minor, patch = parse_semver(prev_version)
        if level == "major":
            major += 1
            minor = 0
            patch = 0
        elif level == "minor":
            minor += 1
            patch = 0
        else:
            patch += 1
        return format_semver((major, minor, patch))

    if level == "major":
        return "v1.0.0"
    return "v0.1.0"


def latest_tag_for_slug(slug: str) -> Optional[str]:
    """Return the newest tag matching <slug>-v* sorted by version."""
    tag_list = run_git(["tag", "--list", f"{slug}-v*"])
    if not tag_list:
        return None

    tags = tag_list.splitlines()
    tags.sort(
        key=lambda tag: parse_semver(tag.rsplit("-v", 1)[-1]),
        reverse=True,
    )
    return tags[0]


def latest_test_tag(family_slug: str) -> Optional[str]:
    """Return newest tag for the test branch of a family."""
    test_slug = f"{family_slug}-test" if family_slug else "test"
    return latest_tag_for_slug(test_slug)


def read_version_file(version_path: Path) -> Optional[str]:
    """Read the first non-empty line from a version file, if present."""
    if not version_path.exists():
        return None
    for line in version_path.read_text(encoding="utf-8").splitlines():
        stripped = line.strip()
        if stripped:
            return stripped
    return None


def write_text(path: Path, content: str) -> None:
    """Write content to path, creating parent directories."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")


def determine_level(commit_message: Optional[str]) -> str:
    """Map commit message prefix to bump level."""
    if not commit_message:
        return "patch"

    lowered = commit_message.lower()
    if lowered.startswith("major:"):
        return "major"
    if lowered.startswith("minor:"):
        return "minor"
    if lowered.startswith("fix:"):
        return "patch"
    return "patch"


def latest_commit_message() -> str:
    """Return the most recent commit subject on HEAD."""
    return run_git(["log", "-1", "--pretty=%s"])


@dataclass
class BranchContext:
    branch: str
    family: str
    category: str
    feature_name: Optional[str]

    @property
    def family_dir(self) -> Path:
        if not self.family:
            return Path(".")
        return Path(self.family.upper())

    @property
    def features_root(self) -> Path:
        if self.family:
            return self.family_dir / "feature"
        return Path("feature")

    @property
    def branch_slug(self) -> str:
        return branch_slug(self.branch)

    @property
    def version_file_path(self) -> Path:
        if self.category == "feature":
            return Path("VERSION.txt")
        return Path("VERSION.md")

    @property
    def release_body_path(self) -> Path:
        name = self.branch_slug.replace("-", "_")
        return Path(".github") / "release-notes" / f"{name}.md"

    @property
    def test_branch(self) -> Optional[str]:
        if self.category == "main":
            if self.family:
                return f"{self.family}/test"
            return "test"
        if self.category == "test":
            return None
        return None

    @property
    def family_slug(self) -> str:
        if self.family:
            return self.family.replace("/", "-")
        return ""


def parse_branch(branch: str) -> BranchContext:
    parts = branch.split("/")
    if branch in {"main", "test"}:
        return BranchContext(branch=branch, family="", category=branch, feature_name=None)

    if parts[0] == "feature":
        feature_name = "/".join(parts[1:]) if len(parts) > 1 else None
        return BranchContext(
            branch=branch,
            family="",
            category="feature",
            feature_name=feature_name,
