+    uint8_t  ledGroupIndex;  // Index / LED-Gruppe auf dem Ring
+    int8_t   lives;          // Restpunkte (z.B. 3..0)
+};
+
+struct LichtloserGameState {
+    uint8_t  playerCount;
+    LichtloserPlayerState* players;
+
