+﻿#include "game_lichtloser.h"
+
+#include <Arduino.h>
+
+static uint32_t rand_in_range(uint32_t minVal, uint32_t maxVal) {
+    if (maxVal <= minVal) {
+        return minVal;
+    }
+    // random(min, maxExclusive)
+    return random(minVal, maxVal + 1);
+}
+
+void lichtloser_init(LichtloserGameState& gameState,
+                     LichtloserPlayerState* players,
+                     uint8_t playerCount,
+                     uint8_t initialLedIndex) {
+    gameState.playerCount       = playerCount;
+    gameState.players           = players;
+    gameState.currentLedIndex   = initialLedIndex;
+    gameState.spinInProgress    = false;
+    gameState.buttonEnabled     = true;
+    gameState.spinEndTimeMs     = 0;
+    gameState.buttonEnableTimeMs= 0;
+    gameState.lastHitPlayer     = -1;
+}
+
+int8_t lichtloser_player_for_led(const LichtloserGameState& gameState, uint8_t ledIndex) {
+    for (uint8_t i = 0; i < gameState.playerCount; ++i) {
+        if (gameState.players[i].ledGroupIndex == ledIndex) {
+            return static_cast<int8_t>(i);
+        }
+    }
+    return -1;
+}
+
+bool lichtloser_start_spin(LichtloserGameState& gameState,
+                           const LichtloserTimingConfig& timing) {
+    if (!gameState.buttonEnabled || gameState.spinInProgress) {
+        return false;
+    }
+
+    if (timing.stepMs == 0) {
+        return false;
+    }
+
+    uint32_t durationMs = rand_in_range(timing.minDurationMs, timing.maxDurationMs);
+    if (durationMs < timing.stepMs) {
+        durationMs = timing.stepMs;
+    }
+
+    uint32_t steps = durationMs / timing.stepMs;
+    if (steps == 0) {
+        steps = 1;
+    }
+
+    uint32_t ledCount = 0;
+    for (uint8_t i = 0; i < gameState.playerCount; ++i) {
+        if (gameState.players[i].ledGroupIndex + 1 > ledCount) {
+            ledCount = gameState.players[i].ledGroupIndex + 1;
+        }
+    }
+    if (ledCount == 0) {
+        return false;
+    }
+
+    uint8_t startIndex = gameState.currentLedIndex;
+    uint8_t endIndex   = (startIndex + (steps % ledCount)) % ledCount;
+
+    uint32_t now = millis();
+    gameState.spinInProgress     = true;
+    gameState.buttonEnabled      = false;
+    gameState.spinEndTimeMs      = now + durationMs;
+    gameState.buttonEnableTimeMs = gameState.spinEndTimeMs + 2000;
+    gameState.lastHitPlayer      = -1;
+
+    gameState.currentLedIndex    = endIndex;
+
+    return true;
+}
+
+void lichtloser_update(LichtloserGameState& gameState) {
+    uint32_t now = millis();
+
+    if (gameState.spinInProgress && now >= gameState.spinEndTimeMs) {
+        gameState.spinInProgress = false;
+
+        int8_t hitPlayer = lichtloser_player_for_led(gameState, gameState.currentLedIndex);
+        if (hitPlayer >= 0) {
+            if (gameState.players[hitPlayer].lives > 0) {
+                gameState.players[hitPlayer].lives -= 1;
+            }
+            gameState.lastHitPlayer = hitPlayer;
+        } else {
+            gameState.lastHitPlayer = -1;
+        }
+    }
+
+    if (!gameState.buttonEnabled && now >= gameState.buttonEnableTimeMs) {
+        gameState.buttonEnabled = true;
+    }
+}
+
+bool lichtloser_consume_hit(LichtloserGameState& gameState, int8_t& hitPlayerIndex) {
+    if (gameState.lastHitPlayer < 0) {
+        return false;
+    }
+    hitPlayerIndex = gameState.lastHitPlayer;
+    gameState.lastHitPlayer = -1;
+    return true;
+}
+
+void lichtloser_build_and_send_spin_command(const LichtloserGameState& gameState,
+                                            const LichtloserTimingConfig& timing,
+                                            LichtloserSendFn sendFn) {
+    if (!sendFn) {
+        return;
+    }
+
+    if (timing.stepMs == 0) {
+        return;
+    }
+
+    uint32_t durationMs = rand_in_range(timing.minDurationMs, timing.maxDurationMs);
+    if (durationMs < timing.stepMs) {
+        durationMs = timing.stepMs;
+    }
+
+    uint32_t steps = durationMs / timing.stepMs;
+    if (steps == 0) {
+        steps = 1;
+    }
+
+    uint8_t startIndex = gameState.currentLedIndex;
+
+    char buf[64];
+    snprintf(buf, sizeof(buf), "SPIN %u %lu %u %u\n",
+             static_cast<unsigned>(startIndex),
+             static_cast<unsigned long>(steps),
+             static_cast<unsigned>(timing.stepMs),
+             static_cast<unsigned>(timing.blinkMs));
+
+    sendFn(buf);
+}
