+﻿#include <Arduino.h>
+
+// Diese Sketch-Datei nimmt ausschließlich Befehle vom ESP entgegen
+// und steuert den LED-Ring. Alle Spiel- und Punkte-Logik liegt auf dem ESP.
+//
+// Protokoll (von ESP kommend, ASCII):
+//   SPIN <startIndex> <steps> <stepMs> <blinkMs>\n
+//
+// Die MEGA führt:
+//  - eine Spin-Phase mit steps Schritten à stepMs aus
+//  - danach Blinken auf endIndex mit Periode blinkMs, bis der nächste SPIN kommt.
+
+// TODO: Passe diese Werte an deine Hardware an:
+static const uint8_t LED_PIN      = 6;   // Datapin deines LED-Rings
+static const uint16_t LED_COUNT   = 60;  // Anzahl LEDs im Ring
+
+// Seriell vom ESP (anpassen je nach Verdrahtung)
+#define ESP_SERIAL Serial1
+static const uint32_t ESP_BAUD = 115200;
+
+enum class RingState {
+    IDLE,
+    SPINNING,
+    BLINKING
+};
+
+struct SpinCommand {
+    uint16_t startIndex;
+    uint32_t steps;
+    uint16_t stepMs;
+    uint16_t blinkMs;
+};
+
+static RingState g_state = RingState::IDLE;
+static SpinCommand g_cmd;
+
+static uint16_t g_currentIndex   = 0;
+static uint32_t g_stepCounter    = 0;
+static uint32_t g_lastStepTime   = 0;
+
+static bool     g_blinkOn        = true;
+static uint32_t g_lastBlinkTime  = 0;
+
+// ------------------------------------------------------------
+// Hier bitte deine LED-Library einbinden und die folgenden
+// drei Funktionen mit echter LED-Ansteuerung füllen.
+// ------------------------------------------------------------
+
+static void leds_init() {
+    // Beispiel:
+    // FastLED.addLeds<NEOPIXEL, LED_PIN>(leds, LED_COUNT);
+    // FastLED.clear(true);
+}
+
+static void leds_show_index(uint16_t index) {
+    // Lösche alle LEDs und setze nur index auf z.B. Rot.
+    // Achte auf index < LED_COUNT.
+}
+
+static void leds_show_off() {
+    // Alle LEDs aus.
+}
+
+static void leds_show_blink(uint16_t index, bool on) {
+    if (on) {
+        leds_show_index(index);
+    } else {
+        leds_show_off();
+    }
+}
+
+// ------------------------------------------------------------
+
+static bool parseSpinCommand(const char* line, SpinCommand& cmd) {
+    if (strncmp(line, "SPIN", 4) != 0) {
+        return false;
+    }
+
+    uint16_t startIndex = 0;
+    uint32_t steps      = 0;
+    uint16_t stepMs     = 0;
+    uint16_t blinkMs    = 0;
+
+    int scanned = sscanf(line + 4, "%hu %lu %hu %hu",
+                         &startIndex,
+                         &steps,
+                         &stepMs,
+                         &blinkMs);
+    if (scanned != 4) {
+        return false;
+    }
+
+    if (stepMs == 0 || steps == 0) {
+        return false;
+    }
+
+    cmd.startIndex = startIndex % LED_COUNT;
+    cmd.steps      = steps;
+    cmd.stepMs     = stepMs;
+    cmd.blinkMs    = blinkMs;
+    return true;
+}
+
+static void applySpinCommand(const SpinCommand& cmd) {
+    g_cmd = cmd;
+    g_state = RingState::SPINNING;
+
+    g_currentIndex  = g_cmd.startIndex % LED_COUNT;
+    g_stepCounter   = 0;
+    g_lastStepTime  = millis();
+
+    leds_show_index(g_currentIndex);
+}
+
+static void handleSerialFromEsp() {
+    static char lineBuf[64];
+    static uint8_t pos = 0;
+
+    while (ESP_SERIAL.available() > 0) {
+        int c = ESP_SERIAL.read();
+        if (c < 0) {
+            break;
+        }
+
+        if (c == '\n' || c == '\r') {
+            if (pos > 0) {
+                lineBuf[pos] = '\0';
+                SpinCommand cmd;
+                if (parseSpinCommand(lineBuf, cmd)) {
+                    applySpinCommand(cmd);
+                }
+                pos = 0;
+            }
+        } else {
+            if (pos < sizeof(lineBuf) - 1) {
+                lineBuf[pos++] = (char)c;
+            }
+        }
+    }
+}
+
+static void updateRing() {
+    uint32_t now = millis();
+
+    switch (g_state) {
+        case RingState::IDLE:
+            break;
+
+        case RingState::SPINNING:
+            if (now - g_lastStepTime >= g_cmd.stepMs) {
+                g_lastStepTime = now;
+
+                g_currentIndex = (g_currentIndex + 1) % LED_COUNT;
+                leds_show_index(g_currentIndex);
+
+                g_stepCounter++;
+                if (g_stepCounter >= g_cmd.steps) {
+                    g_state = RingState::BLINKING;
+                    g_blinkOn = true;
+                    g_lastBlinkTime = now;
+                }
+            }
+            break;
+
+        case RingState::BLINKING:
+            if (g_cmd.blinkMs > 0 && (now - g_lastBlinkTime >= g_cmd.blinkMs)) {
+                g_lastBlinkTime = now;
+                g_blinkOn = !g_blinkOn;
+                leds_show_blink(g_currentIndex, g_blinkOn);
+            }
+            break;
+    }
+}
+
+void setup() {
+    ESP_SERIAL.begin(ESP_BAUD);
+    leds_init();
+    leds_show_off();
+}
+
+void loop() {
+    handleSerialFromEsp();
+    updateRing();
+}
+
