+  int dMin = gv_i(FLOW_GLOBAL_VARIABLE_LL_DECEL_TURNS_MIN10);
+  int dMax = gv_i(FLOW_GLOBAL_VARIABLE_LL_DECEL_TURNS_MAX10);
