static void rs485Poll() {
  while (RS485.available()) {
    int b = RS485.read();
    char c = (char)b;

    // Roh-Log zum Debuggen
    USBSerial.printf("[RS485-BYTE] 0x%02X '%c'\n",
                     b,
                     isprint(c) ? c : '.');

    if (c == '\n') {
      if (rsInLine.length() > 0) {
        logRs485Line("[RS485-RX] ", rsInLine);
        handleRs485Line(rsInLine);
      }
      rsInLine = "";
    } else if (c != '\r') {
      rsInLine += c;
      if (rsInLine.length() > 80) {
        rsInLine = "";
      }
    }
  }
}

