  int oldScore = scores[hitPlayerIndex];

  if (oldScore > 0) {
    scores[hitPlayerIndex] = oldScore - 1;
  }

  // Score zurück in EEZ schreiben
  const int scoreGlobals[6] = {
    FLOW_GLOBAL_VARIABLE_SCORE_P1,
    FLOW_GLOBAL_VARIABLE_SCORE_P2,
    FLOW_GLOBAL_VARIABLE_SCORE_P3,
    FLOW_GLOBAL_VARIABLE_SCORE_P4,
    FLOW_GLOBAL_VARIABLE_SCORE_P5,
    FLOW_GLOBAL_VARIABLE_SCORE_P6
  };

  for (int i = 0; i < playerCount; ++i) {
    eez::flow::setGlobalVariable(scoreGlobals[i], eez::IntegerValue(scores[i]));
  }

  // lastHitPlayer für UI-Blink
  eez::flow::setGlobalVariable(
      FLOW_GLOBAL_VARIABLE_LAST_HIT_PLAYER,
      eez::IntegerValue(hitPlayerIndex));

